public async Task<Product?> DeserializeFromPipeAsync(
    PipeReader reader,
    JsonSerializerOptions options,
    CancellationToken ct)
{
    while (true)
    {
        ReadResult result = await reader.ReadAsync(ct);
        ReadOnlySequence<byte> buffer = result.Buffer;

        if (TryParseProduct(buffer, out Product? product, options))
        {
            reader.AdvanceTo(buffer.End);
            return product;
        }

        reader.AdvanceTo(buffer.Start, buffer.End);

        if (result.IsCompleted) break;
    }

    return null;
}

private bool TryParseProduct(
    ReadOnlySequence<byte> buffer,
    out Product? product,
    JsonSerializerOptions options)
{
    var reader = new Utf8JsonReader(buffer);
    return JsonSerializer.TryParseValue(ref reader, out product, options);
}

app.MapPost("/batch-import", async (HttpRequest request) =>
{
    var products = request.BodyReader.DeserializeAsyncEnumerable<Product>(
        new JsonSerializerOptions { PropertyNameCaseInsensitive = true });

    await foreach (var product in products)
    {
        _db.Products.Add(product);
    }

    await _db.SaveChangesAsync();
    return TypedResults.Ok(new { Imported = true });
})
